static <K, V> void forceExpandSegment(Cache<K, V> cache, K key) {
  checkNotNull(cache);
  checkNotNull(key);
  LocalCache<K, V> map = toLocalCache(cache);
  int hash = map.hash(key);
  Segment<K, V> segment = map.segmentFor(hash);
  segment.expand();
}

